import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate } from "react-router-dom";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";
import Form from "react-bootstrap/Form";
import Alert from "react-bootstrap/Alert";

const AdmListAluno = () => {
  const [alunos, setAlunos] = useState([]);
  const [filtro, setFiltro] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [selectedAlunos, setSelectedAlunos] = useState([]);
  const [certificadoData, setCertificadoData] = useState({
    assunto: "Certificado de Conclusão de Curso",
    mensagemPadrao:
      "Prezado(a) {NOME_ALUNO},\n\nConforme registro acadêmico, confirmamos a conclusão com êxito do curso {NOME_CURSO}.\n\nAgradecemos sua dedicação e esforço.\n\nAtenciosamente,\nEquipe EducaWeb",
  });
  const [statusEnvio, setStatusEnvio] = useState({});
  const navigate = useNavigate();

  // Buscar alunos com informações de curso
  const fetchAlunos = async () => {
    try {
      const resposta = await fetch("http://localhost:5000/alunos");
      if (resposta.ok) {
        const dados = await resposta.json();
        // Adicionar verificação de curso para cada aluno
        const alunosComStatusCurso = await Promise.all(
          dados.map(async (aluno) => {
            const resCurso = await fetch(
              `http://localhost:5000/alunos/${aluno.aluno.id}/listacursos`
            );
            const cursoData = await resCurso.json();
            return {
              ...aluno,
              possuiCurso: cursoData.length > 0,
              curso: cursoData[0]?.nome || "Nenhum curso atribuído",
            };
          })
        );
        setAlunos(alunosComStatusCurso);
      } else {
        console.error("Erro ao buscar alunos");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  useEffect(() => {
    fetchAlunos();
  }, []);

  // Filtrando alunos pelo nome
  const alunosFiltrados = alunos.filter((aluno) =>
    aluno.nome.toLowerCase().includes(filtro.toLowerCase())
  );

  // Manipular seleção de alunos
  const handleSelectAluno = (alunoId) => {
    const aluno = alunos.find((a) => a.id === alunoId);
    if (!aluno.possuiCurso) {
      alert(
        "Este aluno não possui curso atribuído. Atribua um curso antes de emitir o certificado."
      );
      return;
    }
    setSelectedAlunos((prev) => {
      if (prev.includes(alunoId)) {
        return prev.filter((id) => id !== alunoId);
      } else {
        return [...prev, alunoId];
      }
    });
  };

  // Gerar PDF do certificado (simulação - na prática seria feito no backend)
  const gerarCertificadoPDF = async (aluno) => {
    // Na implementação real, isso seria uma chamada para o backend
    // que geraria o PDF com base em um template
    return new Blob([`Certificado para ${aluno.nome}`], {
      type: "application/pdf",
    });
  };

  // Enviar certificados com tratamento profissional
  const enviarCertificados = async () => {
    setStatusEnvio({});
    const alunosParaEnviar = alunos.filter((aluno) =>
      selectedAlunos.includes(aluno.id)
    );

    try {
      for (const aluno of alunosParaEnviar) {
        try {
          if (!aluno.possuiCurso) {
            setStatusEnvio((prev) => ({
              ...prev,
              [aluno.id]: { status: "error", message: "Sem curso atribuído" },
            }));
            continue;
          }

          // Personalizar mensagem
          const mensagemPersonalizada = certificadoData.mensagemPadrao
            .replace(/{NOME_ALUNO}/g, aluno.nome)
            .replace(/{NOME_CURSO}/g, aluno.curso);

          // Gerar certificado PDF (simulado)
          const certificadoPDF = await gerarCertificadoPDF(aluno);

          // Criar FormData para enviar o PDF como anexo
          const formData = new FormData();
          formData.append("to", aluno.email);
          formData.append("subject", certificadoData.assunto);
          formData.append("text", mensagemPersonalizada);
          formData.append(
            "anexo",
            certificadoPDF,
            `Certificado_${aluno.nome}.pdf`
          );

          const response = await fetch("http://localhost:5000/email", {
            method: "POST",
            body: formData,
          });

          if (response.ok) {
            setStatusEnvio((prev) => ({
              ...prev,
              [aluno.id]: { status: "success", message: "Enviado com sucesso" },
            }));
          } else {
            throw new Error(`Status ${response.status}`);
          }
        } catch (error) {
          console.error(`Falha no envio para ${aluno.nome}:`, error);
          setStatusEnvio((prev) => ({
            ...prev,
            [aluno.id]: { status: "error", message: "Falha no envio" },
          }));
        }
      }
    } catch (error) {
      console.error("Erro geral no processo:", error);
    }
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">
        EducaWeb - Portal Administrativo
      </h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistcurso">
            Gestão de Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistprof">
            Gestão de Docentes
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link active" href="">
            Gestão de Discentes
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-between align-items-center mt-4">
        <h2 className="mb-0">Registro Acadêmico de Discentes</h2>
        <div>
          <button
            className="btn btn-success mx-2"
            onClick={() => setShowModal(true)}
            disabled={alunos.length === 0}
          >
            <i className="fas fa-certificate me-2"></i>
            Emitir Certificados
          </button>
          <button
            className="btn btn-primary"
            onClick={() => navigate("/admaddaluno")}
          >
            <i className="fas fa-user-plus me-2"></i>
            Cadastrar Novo Discente
          </button>
        </div>
      </div>

      <div className="mt-3">
        <input
          type="text"
          className="form-control"
          placeholder="Filtrar discentes por nome"
          value={filtro}
          onChange={(e) => setFiltro(e.target.value)}
        />
      </div>

      <div className="table-responsive mt-3">
        <table className="table table-hover align-middle">
          <thead className="table-light">
            <tr>
              <th width="50px">Seleção</th>
              <th>Nome do Discente</th>
              <th>Curso Matriculado</th>
              <th>Status</th>
              <th className="text-end">Ações</th>
            </tr>
          </thead>
          <tbody>
            {alunosFiltrados.map((aluno) => (
              <tr key={aluno.id}>
                <td>
                  <Form.Check
                    type="checkbox"
                    checked={selectedAlunos.includes(aluno.id)}
                    onChange={() => handleSelectAluno(aluno.id)}
                    disabled={!aluno.possuiCurso}
                    title={
                      !aluno.possuiCurso
                        ? "Atribua um curso antes de selecionar"
                        : ""
                    }
                  />
                </td>
                <td>
                  <span
                    className="text-primary cursor-pointer"
                    onClick={() => navigate(`/adminfaluno/${aluno.aluno.id}`)}
                  >
                    {aluno.nome}
                  </span>
                </td>
                <td>
                  {aluno.possuiCurso ? (
                    <span className="badge bg-success">{aluno.curso}</span>
                  ) : (
                    <span className="badge bg-warning text-dark">
                      Sem curso
                    </span>
                  )}
                </td>
                <td>
                  {statusEnvio[aluno.id] && (
                    <span
                      className={`badge bg-${
                        statusEnvio[aluno.id].status === "success"
                          ? "success"
                          : "danger"
                      }`}
                    >
                      {statusEnvio[aluno.id].message}
                    </span>
                  )}
                </td>
                <td className="text-end">
                  <button
                    className="btn btn-sm btn-outline-primary mx-1"
                    onClick={() => navigate(`/admeditaluno/${aluno.aluno.id}`)}
                  >
                    <i className="fas fa-edit"></i> Editar
                  </button>
                  <button
                    className="btn btn-sm btn-outline-danger"
                    onClick={() => removerAluno(aluno.id)}
                  >
                    <i className="fas fa-trash-alt"></i> Remover
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Modal de Emissão de Certificados */}
      <Modal
        show={showModal}
        onHide={() => setShowModal(false)}
        size="lg"
        centered
      >
        <Modal.Header closeButton className="bg-primary text-white">
          <Modal.Title>
            <i className="fas fa-certificate me-2"></i>
            Emissão de Certificados Acadêmicos
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Assunto do E-mail</Form.Label>
              <Form.Control
                type="text"
                value={certificadoData.assunto}
                onChange={(e) =>
                  setCertificadoData({
                    ...certificadoData,
                    assunto: e.target.value,
                  })
                }
                placeholder="Ex: Certificado de Conclusão - Curso de Formação Profissional"
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Template da Mensagem</Form.Label>
              <Form.Control
                as="textarea"
                rows={5}
                value={certificadoData.mensagemPadrao}
                onChange={(e) =>
                  setCertificadoData({
                    ...certificadoData,
                    mensagemPadrao: e.target.value,
                  })
                }
              />
              <Form.Text className="text-muted">
                Utilize as variáveis {`{NOME_ALUNO}`} e {`{NOME_CURSO}`} para
                personalização automática.
              </Form.Text>
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Discentes Selecionados para Emissão</Form.Label>
              {selectedAlunos.length === 0 ? (
                <Alert variant="warning">Nenhum discente selecionado</Alert>
              ) : (
                <div
                  className="border rounded p-2"
                  style={{ maxHeight: "200px", overflowY: "auto" }}
                >
                  <ul className="list-unstyled mb-0">
                    {alunos
                      .filter((aluno) => selectedAlunos.includes(aluno.id))
                      .map((aluno) => (
                        <li key={aluno.id} className="py-2 border-bottom">
                          <div className="d-flex justify-content-between align-items-center">
                            <div>
                              <strong>{aluno.nome}</strong>
                              <div className="text-muted small">
                                {aluno.email}
                              </div>
                              <div>
                                Curso:{" "}
                                <span className="badge bg-info">
                                  {aluno.curso}
                                </span>
                              </div>
                            </div>
                            {statusEnvio[aluno.id] && (
                              <span
                                className={`badge bg-${
                                  statusEnvio[aluno.id].status === "success"
                                    ? "success"
                                    : "danger"
                                }`}
                              >
                                {statusEnvio[aluno.id].message}
                              </span>
                            )}
                          </div>
                        </li>
                      ))}
                  </ul>
                </div>
              )}
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            <i className="fas fa-times me-2"></i> Cancelar
          </Button>
          <Button
            variant="primary"
            onClick={enviarCertificados}
            disabled={selectedAlunos.length === 0}
          >
            <i className="fas fa-paper-plane me-2"></i> Confirmar Emissão
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default AdmListAluno;
